/* ---------- Scratch cards: nine squares, match three to win (98% RTP) ---------- */
const SCRATCH = [['crown', 'Crown', 100, 10], ['diamond', 'Diamond', 20, 50], ['star', 'Star', 10, 120], ['clover', 'Clover', 5, 300], ['bell', 'Bell', 2, 900], ['coin', 'Coin', 1, 3300]]; // key, label, pays ×, chance out of 10,000
// Builds a card with exactly three of the winning symbol (win = index) or, for a losing card (win = -1), no symbol three times.
function scratchGrid(win, rint) {
  const cells = win >= 0 ? [win, win, win] : [];
  const count = SCRATCH.map(() => 0);
  while (cells.length < 9) {
    const ok = SCRATCH.map((_, i) => i).filter(i => i !== win && count[i] < 2);
    const s = ok[rint(ok.length)];
    count[s]++; cells.push(s);
  }
  for (let i = cells.length - 1; i > 0; i--) { const j = rint(i + 1); [cells[i], cells[j]] = [cells[j], cells[i]]; }
  return cells;
}

